use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut prev_quote = false
        for c in line.chars() {
            if inq {
                if c == '"' {
                    if prev_quote {
                        cur = cur + "\""
                        prev_quote = false
                    } else {
                        prev_quote = true
                    }
                } else {
                    if prev_quote {
                        inq = false
                        prev_quote = false
                        if c == ',' {
                            fields.push(cur)
                            cur = ""
                        } else {
                            cur = cur + c.to_string()
                        }
                    } else {
                        cur = cur + c.to_string()
                    }
                }
            } else {
                if c == ',' {
                    fields.push(cur)
                    cur = ""
                } else if c == '"' {
                    inq = true
                    prev_quote = false
                } else {
                    cur = cur + c.to_string()
                }
            }
        }
        fields.push(cur)
        let mut out = ""
        let mut i = 0
        for f in fields {
            if i > 0 {
                out = out + "|"
            }
            out = out + "[" + f + "]"
            i += 1
        }
        println("${i}: ${out}")
    }
}

